def compute(vars):
    cash = vars["v1"]
    short_term_investments = vars["v2"]
    accounts_receivable = vars["v3"]
    current_liabilities = vars["v4"]

    if current_liabilities == 0:
        return None

    liquid_assets = cash + short_term_investments + accounts_receivable
    acid_test_ratio = round(liquid_assets / current_liabilities, 2)

    return {
        "value": acid_test_ratio,
        "trace": {
            "Cash": cash,
            "Short-term Investments": short_term_investments,
            "Accounts Receivable": accounts_receivable,
            "Current Liabilities": current_liabilities,
            "Liquid Assets": liquid_assets,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
